const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));
const localDate = new Date(Date.UTC(Number(parts.year),Number(parts.month)-1,Number(parts.day)));
const monday = new Date(localDate);
monday.setUTCDate(monday.getUTCDate()-((monday.getUTCDay()+6)%7));
const iso = d => d.toISOString().slice(0,10);
const items = [
 {offset:0,time:'09:00',kind:'Artigo educativo',task:'Preparar um artigo informativo vinculado a uma das 15 áreas de atuação.',channel:'Site + Facebook',review:'Revisão jurídica e de fontes obrigatória.'},
 {offset:1,time:'12:00',kind:'Roteiro de vídeo curto',task:'Preparar roteiro de 30–60 segundos com pergunta frequente e resposta geral.',channel:'TikTok + YouTube Shorts',review:'Confirmar consentimento para voz/imagem e revisar roteiro.'},
 {offset:2,time:'09:00',kind:'Resumo de notícia jurídica',task:'Selecionar notícia de fonte primária, registrar URL e data, escrever resumo próprio e linkar a origem.',channel:'Site + Facebook',review:'Não publicar sem fonte primária conferida.'},
 {offset:3,time:'12:00',kind:'Carrossel educativo',task:'Adaptar um conteúdo já aprovado em 5–7 telas, sem promessa de resultado.',channel:'Facebook; outros canais somente quando conectados',review:'Revisar legibilidade, direitos de imagem e texto jurídico.'},
 {offset:4,time:'09:00',kind:'FAQ / vídeo ou artigo',task:'Responder uma dúvida geral e encaminhar atendimento individual à Central Digital do Cliente.',channel:'Site + YouTube',review:'Consulta Processual não é destino de atendimento geral.'}
];
const schedule = items.map(item=>{const date=new Date(monday);date.setUTCDate(date.getUTCDate()+item.offset);return {...item,date:iso(date)};});
const weekLabel=iso(monday);
const title='Calendário editorial Garibalde — semana de '+weekLabel;
const content='<p><strong>Agenda semanal de produção — rascunho para revisão e aprovação editorial.</strong></p><p>Semana iniciada em '+weekLabel+'. Esta agenda organiza tarefas; não significa que os conteúdos estejam prontos, aprovados ou publicados.</p><ol>'+schedule.map(x=>'<li><h3>'+x.date+' · '+x.time+' — '+x.kind+'</h3><p>'+x.task+'</p><p><strong>Distribuição sugerida:</strong> '+x.channel+'</p><p><strong>Porta de qualidade:</strong> '+x.review+'</p><p><strong>Responsável e fonte:</strong> preencher antes de aprovar.</p></li>').join('')+'</ol><p><strong>Regra de saída:</strong> cada peça exige conferência factual, fonte quando aplicável, revisão humana, aprovação e confirmação da plataforma de destino. Este calendário não aciona publicação social.</p>';
return [{json:{title,content,week_start:weekLabel,items:schedule.length,status:'draft'}}];

const post=$json;
if (!post.id || post.status!=='draft') throw new Error('O WordPress não confirmou a criação da agenda como rascunho.');
return [{json:{ok:true,status:'calendar_draft_created',wp_post_id:post.id,wp_status:post.status,title:post.title?.rendered||'Calendário editorial semanal',link:post.link,agenda_items:5,items_published:false,message:'Agenda criada como rascunho; nenhum item do calendário foi publicado.'}}];
